#!/usr/bin/env bash
# Hermetic regression tests for the explicit MariaDB port command (CLI-30).
# No real MariaDB, service manager, /etc file or site database is touched:
# service/restart/probe/wp helpers are stubbed and the server config path is
# overridden per call. Real service/config mutation is opt-in manual testing.
# shellcheck disable=SC1091 # Compiled CLI is generated by compile.sh.
# shellcheck disable=SC2329 # Stubs are invoked indirectly via the CLI.
set -euo pipefail
ROOT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$ROOT_DIR"
./compile.sh >/dev/null
tmpdir=$(mktemp -d)
trap 'rm -rf "$tmpdir"' EXIT
export HOME="$tmpdir/home" PLAK_NO_PATH_PRELUDE=1 PLAK_TERMINAL_LINKS=0
mkdir -p "$HOME"
source ./plak.sh >/dev/null

fail() { echo "db-port regression failed: $*" >&2; exit 1; }

# --- Hermetic stubs ---
# Reachability is scripted per test via files, never a real socket.
export TEST_LIVE_PORTS="$tmpdir/live"
: > "$TEST_LIVE_PORTS"
mysqladmin() {
    local port="" prev=""
    for arg in "$@"; do
        [ "$prev" = "-P" ] && port="$arg"
        prev="$arg"
    done
    grep -qx "$port" "$TEST_LIVE_PORTS" || return 1
}
port_listening_app() {
    case "$1" in
        9999) echo "redis" ;;
        *) echo "" ;;
    esac
}
port_is_free() {
    grep -qx "$1" "$TEST_LIVE_PORTS" && return 1
    [ "$1" = "9999" ] && return 1
    return 0
}
plak_site_db_restart_mariadb() {
    printf '%s\n' "$DB_PORT" >> "$tmpdir/restarts"
    if [ "${TEST_RESTART_RC:-0}" -eq 0 ] && [ -z "${TEST_NO_LIVE:-}" ]; then
        printf '%s\n' "$DB_PORT" >> "$TEST_LIVE_PORTS"
    fi
    return "${TEST_RESTART_RC:-0}"
}
plak_multisite_wp() {
    local public="$1"; shift
    printf '%s|%s\n' "$public" "$*" >> "$tmpdir/wp-calls"
    case "$*" in
        'config get DB_HOST') cat "$public/.db-host" ;;
        'config set DB_HOST '*)
            if [ "${TEST_WP_FAIL_FOR:-}" = "$(basename "$(dirname "$public")")" ]; then
                return 1
            fi
            printf '%s\n' "${*: -1}" > "$public/.db-host"
            ;;
        *) return 1 ;;
    esac
}
gum() { return 0; }
export OS=linux SUDO_CMD=""

make_site() {
    mkdir -p "$SITES_DIR/$1.localhost/public"
    printf '<?php\n' > "$SITES_DIR/$1.localhost/public/wp-config.php"
    printf '%s\n' "$2" > "$SITES_DIR/$1.localhost/public/.db-host"
}
reset_state() {
    rm -rf "$HOME/Plak"
    mkdir -p "$SITES_DIR"
    : > "$TEST_LIVE_PORTS"
    : > "$tmpdir/restarts" 2>/dev/null || true
    : > "$tmpdir/wp-calls" 2>/dev/null || true
    unset TEST_RESTART_RC TEST_WP_FAIL_FOR TEST_NO_LIVE
    printf '3306\n' > "$TEST_LIVE_PORTS"
}

# --- show / validation ---
reset_state
printf "DB_PORT='3306'\nDB_HOST='127.0.0.1'\n" > "$CONFIG_FILE"
out=$(plak_site_db_port)
grep -q 'MariaDB port: 127.0.0.1:3306 (reachable)' <<<"$out" || fail "show reachable: $out"
printf '' > "$TEST_LIVE_PORTS"
out=$(plak_site_db_port)
grep -q '(not answering)' <<<"$out" || fail "show unreachable: $out"
if plak_site_db_port set abc >/dev/null 2>&1; then fail "accepted non-numeric port"; fi
if plak_site_db_port set 0 >/dev/null 2>&1; then fail "accepted port 0"; fi
if plak_site_db_port set 70000 >/dev/null 2>&1; then fail "accepted port 70000"; fi
out=$(plak_site_db_port set 3306)
grep -q 'already 3306' <<<"$out" || fail "same-port no-op: $out"

# --- foreign occupant is refused ---
reset_state
printf "DB_PORT='3306'\nDB_HOST='127.0.0.1'\n" > "$CONFIG_FILE"
if plak_site_db_port set 9999 --yes >/dev/null 2>&1; then fail "accepted foreign-occupied port"; fi
grep -q "DB_PORT='3306'" "$CONFIG_FILE" || fail "config changed after refusal"

# --- dry-run mutates nothing ---
reset_state
printf "DB_PORT='3306'\nDB_HOST='127.0.0.1'\n" > "$CONFIG_FILE"
make_site demo '127.0.0.1:3306'
conf="$tmpdir/plak.cnf"
DB_PORT=3306 plak_site_configure_mariadb_port "$conf"
# dry-run goes through the real path helper; override via function instead:
plak_mariadb_conf_file() { printf '%s\n' "$conf"; }
out=$(plak_site_db_port set 3307 --dry-run)
grep -q 'Would change MariaDB port 3306 -> 3307' <<<"$out" || fail "dry-run plan: $out"
grep -q 'Would update demo.localhost' <<<"$out" || fail "dry-run site plan: $out"
[ ! -s "$tmpdir/restarts" ] || fail "dry-run restarted the service"
grep -q "DB_PORT='3306'" "$CONFIG_FILE" || fail "dry-run changed Plak config"
grep -q 'port=3306' "$conf" || fail "dry-run rewrote the server file"
unset -f plak_mariadb_conf_file

# --- success rewrites server, restarts, verifies, migrates ---
reset_state
printf "DB_PORT='3306'\nDB_HOST='127.0.0.1'\n" > "$CONFIG_FILE"
make_site demo '127.0.0.1:3306'
make_site other '127.0.0.1:3308'
conf="$tmpdir/success.cnf"
plak_mariadb_conf_file() { printf '%s\n' "$conf"; }
plak_site_db_port set 3307 --yes > "$tmpdir/out"
grep -q 'changed 3306 -> 3307' "$tmpdir/out" || fail "success banner missing"
grep -q 'port=3307' "$conf" || fail "server file not rewritten"
grep -q "DB_PORT='3307'" "$CONFIG_FILE" || fail "Plak config not updated"
grep -q '^3307$' "$tmpdir/restarts" || fail "service not restarted for new port"
[ "$(cat "$SITES_DIR/demo.localhost/public/.db-host")" = '127.0.0.1:3307' ] || fail "matching site not migrated"
[ "$(cat "$SITES_DIR/other.localhost/public/.db-host")" = '127.0.0.1:3308' ] || fail "unrelated site rewritten"
unset -f plak_mariadb_conf_file

# --- restart failure rolls back server + config, no migration ---
reset_state
printf "DB_PORT='3306'\nDB_HOST='127.0.0.1'\n" > "$CONFIG_FILE"
make_site demo '127.0.0.1:3306'
conf="$tmpdir/rollback.cnf"
printf '[mysqld]\nport=3306\n' > "$conf"
plak_mariadb_conf_file() { printf '%s\n' "$conf"; }
TEST_RESTART_RC=1
if plak_site_db_port set 3307 --yes > "$tmpdir/out" 2>&1; then fail "restart failure reported success"; fi
grep -qi 'restored' "$tmpdir/out" || fail "rollback not reported"
grep -q 'port=3306' "$conf" || fail "server file not restored"
grep -q "DB_PORT='3306'" "$CONFIG_FILE" || fail "Plak config not restored"
[ "$(cat "$SITES_DIR/demo.localhost/public/.db-host")" = '127.0.0.1:3306' ] || fail "site migrated despite rollback"
unset -f plak_mariadb_conf_file
unset TEST_RESTART_RC

# --- verification timeout rolls back too ---
reset_state
printf "DB_PORT='3306'\nDB_HOST='127.0.0.1'\n" > "$CONFIG_FILE"
conf="$tmpdir/timeout.cnf"
printf '[mysqld]\nport=3306\n' > "$conf"
plak_mariadb_conf_file() { printf '%s\n' "$conf"; }
# Restart succeeds but the new port never answers: the verify loop must time
# out and roll back. Speed up: stub sleep to avoid 20s.
TEST_NO_LIVE=1
sleep() { :; }
if plak_site_db_port set 3307 --yes > "$tmpdir/out" 2>&1; then fail "timeout reported success"; fi
grep -qi 'did not become available.*restored' "$tmpdir/out" || fail "timeout rollback not reported"
grep -q "DB_PORT='3306'" "$CONFIG_FILE" || fail "config not restored after timeout"
unset -f plak_mariadb_conf_file
unset -f sleep

# --- target already serving MariaDB: adopt without rewrite ---
reset_state
printf "DB_PORT='3306'\nDB_HOST='127.0.0.1'\n" > "$CONFIG_FILE"
make_site demo '127.0.0.1:3306'
printf '3308\n' >> "$TEST_LIVE_PORTS"
conf="$tmpdir/adopt.cnf"
printf '[mysqld]\nport=3306\n' > "$conf"
plak_mariadb_conf_file() { printf '%s\n' "$conf"; }
plak_site_db_port set 3308 --yes > "$tmpdir/out"
grep -q 'port=3306' "$conf" || fail "adopt path rewrote a serving config"
[ ! -s "$tmpdir/restarts" ] || fail "adopt path restarted unnecessarily"
grep -q "DB_PORT='3308'" "$CONFIG_FILE" || fail "adopt path did not update Plak config"
[ "$(cat "$SITES_DIR/demo.localhost/public/.db-host")" = '127.0.0.1:3308' ] || fail "adopt path did not migrate sites"
unset -f plak_mariadb_conf_file

# --- site migration failure keeps the healthy server, reports sites ---
reset_state
printf "DB_PORT='3306'\nDB_HOST='127.0.0.1'\n" > "$CONFIG_FILE"
make_site good '127.0.0.1:3306'
make_site bad '127.0.0.1:3306'
conf="$tmpdir/partial.cnf"
plak_mariadb_conf_file() { printf '%s\n' "$conf"; }
TEST_WP_FAIL_FOR=bad.localhost
if plak_site_db_port set 3307 --yes > "$tmpdir/out" 2>&1; then fail "partial migration reported success"; fi
grep -q 'bad.localhost' "$tmpdir/out" || fail "failed site not named"
grep -q 'port=3307' "$conf" || fail "healthy server change was rolled back on site failure"
[ "$(cat "$SITES_DIR/good.localhost/public/.db-host")" = '127.0.0.1:3307' ] || fail "healthy site not migrated"
unset -f plak_mariadb_conf_file

echo 'db-port regression tests passed'
